body.script:
(function () {
    var width = parseInt(document.body.dataset.width, 10) || 576;
    var method = document.body.dataset.method || "intent";
    function ticket(label, format) {
        var c = document.createElement("canvas");
        c.width = width; c.height = 560;
        var g = c.getContext("2d");
        g.fillStyle = "#fff"; g.fillRect(0, 0, c.width, c.height);
        g.strokeStyle = "#000"; g.lineWidth = 4; g.strokeRect(2, 2, c.width - 4, c.height - 4);
        g.fillStyle = "#000"; g.textAlign = "center";
        g.font = "bold 44px sans-serif"; g.fillText("TEST " + label, c.width / 2, 70);
        g.font = "28px sans-serif";
        var y = 110;
        ["RawBT " + (width === 576 ? "80 mm" : "58 mm"), new Date().toLocaleString(),
         "Anillo de compromiso 14K", "Total $14,551.07", "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
         "abcdefghijklmnopqrstuvwxyz", "0123456789 $ , . - /", "Gracias por su visita",
         "Anello"].forEach(function (line) { g.fillText(line, c.width / 2, y); y += 46; });
        return window.XbRawBT.job(c, width, format);
    }
    var log = document.getElementById("log");
    document.querySelectorAll("button").forEach(function (btn) {
        btn.addEventListener("click", function () {
            var label = btn.querySelector("b").textContent;
            var job = ticket(label, btn.dataset.format);
            log.textContent = "Sent " + label + ".";
            window.XbRawBT.send(job[0], method, job[1]);
        });
    });
})();
